def kthOfTwoSorted(a, b, k):
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    lo, hi = max(0, k - n), min(k, m)
    while lo < hi:
        i = (lo + hi) // 2
        j = k - i
        if a[i] < b[j - 1]:
            lo = i + 1
        else:
            hi = i
    i = lo
    j = k - i
    best = []
    if i > 0:
        best.append(a[i - 1])
    if j > 0:
        best.append(b[j - 1])
    return max(best)
